import random
import networkx as nx

def calculate_s(G):
    s = 0
    degrees = dict(G.degree())
    for u, v in G.edges():
        s += abs(degrees[u] - degrees[v])
    return s

def hill_climbing(n, iterations=1000):
    G = nx.gnp_random_graph(n, 0.5)
    current_s = calculate_s(G)

    for _ in range(iterations):
        u, v = random.sample(range(n), 2)
        if G.has_edge(u, v):
            G.remove_edge(u, v)
            new_s = calculate_s(G)
            if new_s >= current_s:
                current_s = new_s
            else:
                G.add_edge(u, v)
        else:
            G.add_edge(u, v)
            new_s = calculate_s(G)
            if new_s >= current_s:
                current_s = new_s
            else:
                G.remove_edge(u, v)
    return current_s

n = 11
max_s = 0
for _ in range(100):
    max_s = max(max_s, hill_climbing(n))
print(f"Max S found by local search: {max_s}")

# Also check K_{k, n-k} again
for k in range(1, n // 2 + 1):
    s = k * (n - k) * abs(n - 2 * k)
    print(f"K_{k, {n-k}}: {s}")

