import random
import networkx as nx
import math

def calculate_s(G):
    s = 0
    degrees = dict(G.degree())
    for u, v in G.edges():
        s += abs(degrees[u] - degrees[v])
    return s

def simulated_annealing(n, initial_temp=10, cooling_rate=0.995, iterations=10000):
    G = nx.gnp_random_graph(n, random.uniform(0, 1))
    current_s = calculate_s(G)
    best_s = current_s
    temp = initial_temp

    for i in range(iterations):
        u, v = random.sample(range(n), 2)
        # Try flipping edge (u, v)
        if G.has_edge(u, v):
            G.remove_edge(u, v)
            new_s = calculate_s(G)
            if new_s > current_s or random.random() < math.exp((new_s - current_s) / temp):
                current_s = new_s
            else:
                G.add_edge(u, v)
        else:
            G.add_edge(u, v)
            new_s = calculate_s(G)
            if new_s > current_s or random.random() < math.exp((new_s - current_s) / temp):
                current_s = new_s
            else:
                G.remove_edge(u, v)

        if current_s > best_s:
            best_s = current_s
        temp *= cooling_rate

    return best_s

n = 11
max_s = 0
for _ in range(20):
    max_s = max(max_s, simulated_annealing(n))
print(f"Global max S found: {max_s}")

